css:
/* concept: Ardoise */
.cs-a{background:#F3ECE1;color:#2C2118;font-family:var(--f-body)}
.c-nav{display:flex;align-items:center;gap:1.4em;padding:1.4em 1.8em;font-size:.85em}
.c-nav b{font-size:1.25em;margin-right:auto}
.cs-a .c-nav b,.cs-a .c-h,.cs-a .c-quote{font-family:var(--f-serif);font-weight:400}
.c-hero{padding:2em 1.8em 1.4em;display:grid;gap:.8em;justify-items:start}
.c-k{font-size:.7em;letter-spacing:.14em;text-transform:uppercase}
.c-h{font-size:3.1em;line-height:.98;letter-spacing:-.01em}
.c-btn{display:inline-block;padding:.7em 1.2em;border-radius:99px;font-size:.8em;font-weight:600}
.cs-a .c-k{color:#8E5428}.cs-a .c-btn{background:#2C2118;color:#F3ECE1}
.c-wood{height:24%;margin:0 1.8em;border-radius:.8em;background:repeating-linear-gradient(96deg,#C99566 0 7px,#B98250 7px 10px,#D3A475 10px 17px,#C08A58 17px 21px)}
.c-row{display:grid;grid-template-columns:repeat(3,1fr);gap:.7em;padding:1em 1.8em}
.c-row i{display:block;aspect-ratio:1;border-radius:.6em}
.cs-a .c-row i:nth-child(1){background:repeating-linear-gradient(80deg,#8C5A33 0 5px,#7A4C2A 5px 8px)}
.cs-a .c-row i:nth-child(2){background:repeating-linear-gradient(100deg,#D9B78F 0 6px,#CBA67B 6px 9px)}
.cs-a .c-row i:nth-child(3){background:repeating-linear-gradient(90deg,#A8754A 0 4px,#946540 4px 7px)}
.c-quote{margin:1.2em 1.8em;padding:1.6em;border-radius:.8em;background:#2C2118;color:#F3ECE1;font-size:1.5em;line-height:1.15}
.c-form{display:grid;gap:.6em;padding:1em 1.8em}
.c-form i{display:block;height:2.2em;border-radius:.5em;background:#fff;border:1px solid #E2D6C4}
.c-form i.big{height:5em}
.c-form .c-btn{justify-self:start}
.c-foot{margin-top:1.4em;padding:1.6em 1.8em;border-top:1px solid #E2D6C4;font-size:.75em;color:#8C7C69}
/* concept: Ondine */
.cs-o{background:#FCE8DF;color:#3B1F2B}
.cs-o .c-nav b{font-family:var(--f-display);font-weight:900;font-stretch:120%;letter-spacing:-.05em}
.o-banner{margin:0 1.8em;padding:.6em;border-radius:99px;background:#3B1F2B;color:#FCE8DF;text-align:center;font-size:.7em;letter-spacing:.12em;text-transform:uppercase}
.o-hero{padding:1.4em 1.8em;display:grid;grid-template-columns:1fr 1fr;gap:1em;align-items:center}
.o-hero .c-h{font-family:var(--f-display);font-weight:900;font-stretch:115%;font-size:3em;letter-spacing:-.05em;text-transform:uppercase;line-height:.9}
.o-blob{aspect-ratio:1;border-radius:46% 54% 38% 62%/52% 40% 60% 48%;background:linear-gradient(135deg,#FF8FA3,#FF5A1F)}
.o-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:.9em;padding:1em 1.8em}
.o-p{display:grid;gap:.4em;font-size:.75em}
.o-p i{display:block;aspect-ratio:1/1.1;border-radius:.8em}
.o-p:nth-child(1) i{background:radial-gradient(circle at 50% 60%,#F4B860 0 30%,#F7D9C4 31%)}
.o-p:nth-child(2) i{background:radial-gradient(ellipse at 50% 55%,#7B3FF2 0 26%,#E9DDF9 27%)}
.o-p:nth-child(3) i{background:radial-gradient(circle at 50% 50%,#1FA971 0 22%,#D6EEDF 23%)}
.o-p:nth-child(4) i{background:radial-gradient(ellipse at 50% 60%,#EE2A7B 0 28%,#F9D3E1 29%)}
.o-p b{display:flex;justify-content:space-between}
.cs-o .c-btn{background:#3B1F2B;color:#FCE8DF}
.cs-o .c-foot{border-color:#F2CFC0;color:#A0707F}
/* concept: Vallès */
.cs-v{background:#12203B;color:#EDE6D6}
.cs-v .c-nav b,.cs-v .c-h{font-family:var(--f-serif);font-weight:400}
.cs-v .c-k{color:#C9A15B}
.cs-v .c-btn{background:#C9A15B;color:#12203B}
.v-dom{display:grid;gap:0;padding:1em 1.8em}
.v-dom span{display:flex;justify-content:space-between;padding:.9em 0;border-bottom:1px solid rgba(237,230,214,.15);font-size:.9em}
.v-dom span::after{content:"→";color:#C9A15B}
.v-rdv{margin:1em 1.8em;padding:1.2em;border-radius:.8em;background:#EDE6D6;color:#12203B;display:grid;gap:.7em}
.v-rdv b{font-family:var(--f-serif);font-weight:400;font-size:1.4em}
.v-slots{display:grid;grid-template-columns:repeat(3,1fr);gap:.5em;font-family:var(--f-mono);font-size:.75em}
.v-slots span{padding:.6em;border:1px solid #C9B98F;border-radius:.4em;text-align:center}
.v-slots span:nth-child(2){background:#12203B;color:#EDE6D6;border-color:#12203B}
.cs-v .c-foot{border-color:rgba(237,230,214,.15);color:#8D96AB}
/* concept: Comptoir */
.cs-c{background:#1E3A2F;color:#F2E9D8}
.cs-c .c-nav b{font-family:var(--f-display);font-weight:800;font-stretch:80%;text-transform:uppercase;letter-spacing:.02em}
.cs-c .c-h{font-family:var(--f-display);font-weight:800;font-stretch:78%;text-transform:uppercase;letter-spacing:-.01em;font-size:3.6em;line-height:.9}
.cs-c .c-h em{font-style:normal;color:#FF8A3D}
.cs-c .c-btn{background:#FF8A3D;color:#1E3A2F}
.c-photo{height:22%;margin:0 1.8em;border-radius:.8em;background:radial-gradient(circle at 30% 50%,#E8B04A 0 14%,transparent 15%),radial-gradient(circle at 62% 46%,#C2452D 0 18%,transparent 19%),radial-gradient(circle at 80% 62%,#8DB255 0 10%,transparent 11%),#2C4A3D}
.menu-l{padding:1.2em 1.8em;display:grid;gap:.1em}
.menu-l p{font-family:var(--f-serif);font-style:italic;font-size:1.3em;color:#FF8A3D;margin-bottom:.4em}
.menu-l span{display:flex;gap:.6em;padding:.55em 0;font-size:.85em;border-bottom:1px dotted rgba(242,233,216,.25)}
.menu-l span b{margin-left:auto;font-family:var(--f-mono);font-weight:500}
.cs-c .c-foot{border-color:rgba(242,233,216,.15);color:#9CB0A6}
